-- Robotics/Embedded/IoT pathway ("Vector Division") Act 20 -- "Mobile
-- Robots" content, inside Arc IV ("Teach Machines Where They Are," Acts
-- 18-24). World row world-vec-mobile-robots already exists (created by
-- 20260813240000). 1 campaign, 2 operations, 12 missions (11 lessons +
-- boss), following the same campaigns -> operations -> missions ->
-- dialogue -> objectives -> challenges -> hints pattern as every other
-- pathway. No new ChallengeType needed -- reuses story_dialogue,
-- investigation, multiple_choice, interactive_diagram, drag_and_drop
-- and boss_encounter. Dr. Lin Ortega teaches differential drive through
-- motion calibration on one drifting warehouse robot; the boss resolves
-- its specific cause (odometry drift confirmed against a coordinate-frame
-- mismatch, a direct callback to Act 18's undocumented facility frame)
-- and then, via Byte's fleet correlation, lands the bible's own stated
-- story beat: several of the fleet's reported "malfunctions" were never
-- malfunctions at all, only the same undocumented-frame drift recognized
-- as a pattern across the whole fleet. Closes on the pivot into Act 21,
-- "Perception."

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-mobile-robots', 'world-vec-mobile-robots', 'mobile-robots', '4C - Mobile Robots', 'Learn how a wheeled mobile robot actually moves and knows where it is -- differential drive, wheel encoders, odometry, the kinematic model, velocity commands, skid and slip, Ackermann and holonomic drive concepts, coordinate transforms, dead reckoning and motion calibration -- while Dr. Lin Ortega diagnoses one robot the floor team has called unreliable for months.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-mobile-robots-1', 'campaign-vec-mobile-robots', 'how-a-robot-actually-moves', 'How a Robot Actually Moves', 'Differential drive, wheel encoders, odometry, the kinematic model, velocity commands, and skid and slip.', 1),
  ('operation-vec-mobile-robots-2', 'campaign-vec-mobile-robots', 'the-map-underneath-it', 'The Map Underneath It', 'Ackermann and holonomic drive concepts, coordinate transforms, dead reckoning, motion calibration, and the robot that drifts.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-mobile-robots-01', 'world-vec-mobile-robots', 'campaign-vec-mobile-robots', 'operation-vec-mobile-robots-1', 'differential-drive', 'Differential Drive', 'A warehouse mobile robot has been reported malfunctioning for months, drifting a little further off its assigned path every week -- and it is not the only one on the list. Dr. Lin Ortega starts with the simplest question: how does a robot like this actually turn.', 'beginner', ARRAY['imani','lin'], null, null, '{"type":"simulation","simulationId":"differential-drive-sim"}'::jsonb, '{"xp":270,"credits":25}'::jsonb, false, 1),
  ('mission-vec-mobile-robots-02', 'world-vec-mobile-robots', 'campaign-vec-mobile-robots', 'operation-vec-mobile-robots-1', 'wheel-encoders', 'Wheel Encoders', 'Before anyone can trust where this robot thinks it is, Lin wants to know exactly what its wheels report -- not distance, not position, just raw rotation, one tick at a time.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-mobile-robots-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"wheel-encoders-sim"}'::jsonb, '{"xp":270,"credits":30}'::jsonb, false, 2),
  ('mission-vec-mobile-robots-03', 'world-vec-mobile-robots', 'campaign-vec-mobile-robots', 'operation-vec-mobile-robots-1', 'odometry', 'Odometry', 'Wheel rotation alone is not a position. Odometry is the running arithmetic that turns a stream of ticks into an estimate of how far, and which way, the robot has actually gone.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-mobile-robots-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"odometry-sim"}'::jsonb, '{"xp":280,"credits":30}'::jsonb, false, 3),
  ('mission-vec-mobile-robots-04', 'world-vec-mobile-robots', 'campaign-vec-mobile-robots', 'operation-vec-mobile-robots-1', 'kinematic-model', 'The Kinematic Model', 'Two wheel speeds do not describe a robot''s motion until something translates them into one forward speed and one turning rate. That translation has a name: the kinematic model.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-mobile-robots-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"kinematic-model-sim"}'::jsonb, '{"xp":280,"credits":35}'::jsonb, false, 4),
  ('mission-vec-mobile-robots-05', 'world-vec-mobile-robots', 'campaign-vec-mobile-robots', 'operation-vec-mobile-robots-1', 'velocity-commands', 'Velocity Commands', 'Nobody drives this robot by naming wheel speeds directly. Every instruction it receives is a velocity command -- and the same kinematic model that describes its motion also has to run backward to produce one.', 'beginner', ARRAY['lin','imani'], '{"requiredMissionIds":["mission-vec-mobile-robots-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"velocity-commands-sim"}'::jsonb, '{"xp":290,"credits":35}'::jsonb, false, 5),
  ('mission-vec-mobile-robots-06', 'world-vec-mobile-robots', 'campaign-vec-mobile-robots', 'operation-vec-mobile-robots-1', 'skid-and-slip', 'Skid and Slip', 'A wheel can spin without the robot actually moving that far, and the robot can move without a wheel spinning enough to explain it. Skid and slip break the one assumption odometry depends on completely.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-mobile-robots-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"skid-and-slip-sim"}'::jsonb, '{"xp":290,"credits":35}'::jsonb, false, 6),
  ('mission-vec-mobile-robots-07', 'world-vec-mobile-robots', 'campaign-vec-mobile-robots', 'operation-vec-mobile-robots-2', 'ackermann-steering-concepts', 'Ackermann Steering Concepts', 'Not every mobile robot steers the way this one does. Ackermann steering, the geometry underneath ordinary cars, turns wheels instead of speeds -- a different drivetrain built around a different constraint.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-mobile-robots-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"ackermann-steering-concepts-sim"}'::jsonb, '{"xp":300,"credits":40}'::jsonb, false, 7),
  ('mission-vec-mobile-robots-08', 'world-vec-mobile-robots', 'campaign-vec-mobile-robots', 'operation-vec-mobile-robots-2', 'holonomic-drive-concepts', 'Holonomic Drive Concepts', 'A holonomic drive can move sideways without turning at all -- a capability this warehouse robot''s wheels were never built to have. Understanding what it cannot do says as much about its drift as anything it can.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-mobile-robots-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"holonomic-drive-concepts-sim"}'::jsonb, '{"xp":300,"credits":40}'::jsonb, false, 8),
  ('mission-vec-mobile-robots-09', 'world-vec-mobile-robots', 'campaign-vec-mobile-robots', 'operation-vec-mobile-robots-2', 'coordinate-transforms', 'Coordinate Transforms', 'A robot''s own sense of where it is lives in one coordinate frame. The facility''s floor plan lives in another. Nothing about either frame guarantees the two ever agree.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-mobile-robots-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"coordinate-transforms-sim"}'::jsonb, '{"xp":310,"credits":40}'::jsonb, false, 9),
  ('mission-vec-mobile-robots-10', 'world-vec-mobile-robots', 'campaign-vec-mobile-robots', 'operation-vec-mobile-robots-2', 'dead-reckoning', 'Dead Reckoning', 'Dead reckoning is what a robot is doing every time it estimates its position from nothing but its own motion -- and it is exactly as trustworthy as the last correction it received, which for this robot was a long time ago.', 'beginner', ARRAY['lin','imani'], '{"requiredMissionIds":["mission-vec-mobile-robots-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"dead-reckoning-sim"}'::jsonb, '{"xp":310,"credits":45}'::jsonb, false, 10),
  ('mission-vec-mobile-robots-11', 'world-vec-mobile-robots', 'campaign-vec-mobile-robots', 'operation-vec-mobile-robots-2', 'motion-calibration', 'Motion Calibration', 'Calibration measures the small physical truths a robot''s firmware assumes about itself -- true wheel diameter, true wheelbase width -- and corrects for whichever ones were never quite right to begin with.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-mobile-robots-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"motion-calibration-sim"}'::jsonb, '{"xp":320,"credits":45}'::jsonb, false, 11),
  ('mission-vec-mobile-robots-12', 'world-vec-mobile-robots', 'campaign-vec-mobile-robots', 'operation-vec-mobile-robots-2', 'the-robot-that-drifts', 'The Robot That Drifts', 'Every concept this Act taught, turned on one drifting robot -- and then, once Byte pulls the fleet-wide data, on every other robot the fleet audit had quietly filed under malfunctioning.', 'boss', ARRAY['imani','lin','byte'], '{"requiredMissionIds":["mission-vec-mobile-robots-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"the-robot-that-drifts-sim"}'::jsonb, '{"xp":1500,"credits":310,"badgeIds":["the-robot-that-drifts"],"skillXp":{"robotics_fundamentals":200}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-mobile-robots-01', 1, 'imani', 'A warehouse mobile robot has been reported malfunctioning for months, drifting off its assigned path a little more every week -- and it is not the only one on the list. Dr. Lin Ortega, this one is yours.'),
  ('mission-vec-mobile-robots-01', 2, 'lin', 'Before I explain what is wrong with it, you need to understand how a robot like this moves at all. Most warehouse robots like this one do not have a steering wheel. They have two independently driven wheels, one on each side, and nothing else that turns.'),
  ('mission-vec-mobile-robots-01', 3, 'lin', 'Drive both wheels at the same speed and it rolls straight. Drive one wheel faster than the other and it curves toward the slower side. Spin the wheels in opposite directions at equal speed and it rotates in place without moving at all. That is the entire steering mechanism -- differential drive, named for the difference between the two wheel speeds.'),
  ('mission-vec-mobile-robots-01', 4, 'imani', 'So whatever caused it to drift, it did not happen because something turned a wheel that was not supposed to turn.'),

  ('mission-vec-mobile-robots-02', 1, 'lin', 'Before I trust anything this robot reports about its own position, I want to see what it actually measures at the lowest level. Every wheel has a wheel encoder bolted to its axle.'),
  ('mission-vec-mobile-robots-02', 2, 'lin', 'An encoder does not know distance and it does not know position. It only counts discrete ticks as the wheel turns -- a fixed number of ticks per full revolution, nothing more.'),
  ('mission-vec-mobile-robots-02', 3, 'lin', 'Multiply ticks by the known wheel circumference and divide by ticks-per-revolution, and only then do you get a distance that wheel actually rolled.'),

  ('mission-vec-mobile-robots-03', 1, 'lin', 'One wheel''s distance is not a position. Odometry is the running arithmetic that turns a continuous stream of tick counts, from both wheels, into an estimate of how far the whole robot has moved and which way it turned.'),
  ('mission-vec-mobile-robots-03', 2, 'lin', 'Every cycle, the robot reads new tick counts, converts them to wheel distances, applies the kinematic model to get a small step of motion, and adds that step onto its last known position. Then it does the exact same thing again, forever.'),
  ('mission-vec-mobile-robots-03', 3, 'byte', 'Which means every estimate depends entirely on the one before it. There is no external check anywhere in that loop unless something outside the wheels tells it otherwise.'),

  ('mission-vec-mobile-robots-04', 1, 'lin', 'Two wheel speeds are not the same thing as one forward speed and one turning rate. Something has to translate between them, and that something is the kinematic model.'),
  ('mission-vec-mobile-robots-04', 2, 'lin', 'For a differential-drive robot, forward speed is the average of the two wheel speeds, and turning rate is proportional to the difference between them, divided by the distance between the wheels -- the robot''s track width.'),
  ('mission-vec-mobile-robots-04', 3, 'lin', 'A wider track width means the same wheel-speed difference produces a gentler turn. A narrower one makes that same difference turn the robot much faster.'),

  ('mission-vec-mobile-robots-05', 1, 'lin', 'Nobody drives this robot by naming wheel speeds directly. The navigation stack sends a velocity command instead -- a desired forward speed and a desired turning rate -- and something else has to work backward from that to the actual wheel speeds.'),
  ('mission-vec-mobile-robots-05', 2, 'lin', 'That something else is the same kinematic model, run in reverse. Give it a forward speed and a turning rate, and it hands back exactly the pair of wheel speeds that would produce that motion.'),
  ('mission-vec-mobile-robots-05', 3, 'imani', 'So if a robot ever executes a velocity command incorrectly, the fault could be in the command it received, or in how it converted that command into wheel speeds. Two very different places to look.'),

  ('mission-vec-mobile-robots-06', 1, 'lin', 'Every equation so far assumes a wheel''s rotation always matches how far the robot actually rolled. That assumption breaks the moment a wheel skids or slips -- spinning without full traction, or being dragged without spinning enough.'),
  ('mission-vec-mobile-robots-06', 2, 'lin', 'A patch of spilled coolant, an overloaded pallet, a worn tread -- any of them can make the encoder report motion that never actually happened, or miss motion that did.'),
  ('mission-vec-mobile-robots-06', 3, 'byte', 'I checked slip against the drift reports across the fleet. It happens, and it does account for some short-term error. It does not come close to explaining drift this large, this consistent, or this slow to build across months of otherwise ordinary operation.'),
  ('mission-vec-mobile-robots-06', 4, 'lin', 'Then slip is not the whole story here. Whatever is actually behind this is patient in a way slip is not.'),

  ('mission-vec-mobile-robots-07', 1, 'lin', 'This robot is differential drive, but it is worth knowing what else is out there before you assume every mobile robot steers the same way. A car does not have two independently driven wheels -- it has front wheels that physically turn.'),
  ('mission-vec-mobile-robots-07', 2, 'lin', 'Ackermann steering is the geometry underneath that turning: the front wheels turn at slightly different angles from each other so that all four wheels can roll without slipping around one common center of rotation. It is a completely different mechanism from ours, built around a completely different constraint.'),

  ('mission-vec-mobile-robots-08', 1, 'lin', 'One more drivetrain worth knowing, because this robot cannot do it. A holonomic drive, usually built from mecanum or omni wheels, can move sideways or diagonally without turning its body first at all.'),
  ('mission-vec-mobile-robots-08', 2, 'lin', 'Differential drive and Ackermann steering are both non-holonomic -- they can only roll forward or backward and turn, never slide sideways. Every drift correction this robot ever makes has to happen through that same forward-and-turn constraint, nothing more direct.'),

  ('mission-vec-mobile-robots-09', 1, 'lin', 'This robot''s odometry lives in its own coordinate frame -- an origin it picked, usually wherever it woke up or docked, with its own axes. The facility''s floor plan lives in an entirely different frame, drawn by whoever surveyed the building.'),
  ('mission-vec-mobile-robots-09', 2, 'lin', 'A coordinate transform is the rotation and translation that maps a point in one frame into the other. Get that transform right, and the two frames agree on where everything is. Get it wrong, or never define it at all, and both frames can be internally perfect and still disagree completely.'),
  ('mission-vec-mobile-robots-09', 3, 'lin', 'We saw exactly this with the arm two Acts ago. Its joint coordinates were always correct for its own base frame. The floor plan was drawn in a different, undocumented frame from decades earlier, and nobody had ever recorded the transform between the two.'),
  ('mission-vec-mobile-robots-09', 4, 'byte', 'I pulled this robot''s onboard map. Its odometry frame is anchored at its charging dock. The facility blueprint it compares against is anchored to a survey marker from a renovation eleven years ago -- and I cannot find a transform recorded between those two origins anywhere in its configuration.'),

  ('mission-vec-mobile-robots-10', 1, 'lin', 'Every position this robot reports between corrections is dead reckoning -- an estimate built purely from its own integrated motion, with nothing external confirming or correcting it along the way.'),
  ('mission-vec-mobile-robots-10', 2, 'lin', 'Dead reckoning is not wrong the instant it starts. It is wrong by an amount that grows the longer it runs uncorrected, because every small error from the last cycle carries forward into the next one instead of resetting.'),
  ('mission-vec-mobile-robots-10', 3, 'imani', 'So a robot that goes weeks without an external correction is not drifting because something broke last week. It has been drifting since the last time anything actually confirmed where it stood.'),

  ('mission-vec-mobile-robots-11', 1, 'lin', 'Some of this robot''s drift is not about frames or integration at all. It is about whether the numbers in its own firmware match the physical machine underneath them -- calibration.'),
  ('mission-vec-mobile-robots-11', 2, 'lin', 'Wheel diameter, track width, encoder scale -- the kinematic model treats all of them as known constants. If the firmware uses a nominal spec value instead of the true, measured value for this exact robot, every single distance it computes is quietly wrong by the same small, consistent amount.'),
  ('mission-vec-mobile-robots-11', 3, 'byte', 'I found exactly that. This robot''s firmware still uses the factory-spec wheel diameter. The actual wheels, worn down after years of use, measure about two percent smaller. Recalibrating closes some of the gap.'),
  ('mission-vec-mobile-robots-11', 4, 'lin', 'Some of it. Not all of it. A two percent wheel error explains part of a slow drift. It does not explain the rest.'),

  ('mission-vec-mobile-robots-12', 1, 'imani', 'The warehouse floor team has been calling this robot unreliable for months. Every week it drifts a little further off its assigned path. Today we find out whether that is a bad robot, or something else entirely.'),
  ('mission-vec-mobile-robots-12', 2, 'lin', 'Nothing about its hardware reports a fault. Wheels nominal, encoders nominal, motors nominal. Whatever this is, it was never going to show up as a broken part.'),
  ('mission-vec-mobile-robots-12', 3, 'byte', 'Before we chase this one robot alone, you should know it is not alone. I pulled six other fleet reports flagged as the same kind of malfunction this year. Understand this one first, and then look at what all of them have in common.'),
  ('mission-vec-mobile-robots-12', 4, 'lin', 'One robot at a time. Walk me through what its own wheel encoders and kinematic model say happened to it first, then we confirm it against the facility map.'),
  ('mission-vec-mobile-robots-12', 5, 'lin', 'Its wheels never lied. Its kinematic model never lied. Every position it logged is exactly where its own math said it was standing.'),
  ('mission-vec-mobile-robots-12', 6, 'imani', 'Then why does the floor team keep finding it somewhere else.'),
  ('mission-vec-mobile-robots-12', 7, 'lin', 'Because the map underneath it is wrong. Its odometry frame and the facility''s floor-plan frame do not agree, and nothing ever recorded the transform between them -- the same undocumented-frame problem we found in the arm, just wearing a different face.'),
  ('mission-vec-mobile-robots-12', 8, 'byte', 'Same signature, six more times. Every robot on this list has been drifting against a facility zone renovated without ever re-surveying its coordinate frame. None of them are broken, Commander. Several of the fleet''s reported malfunctions are not malfunctions at all -- they are ordinary dead-reckoning drift accumulating against maps and coordinate frames that were never updated as the building changed around them, over decades.'),
  ('mission-vec-mobile-robots-12', 9, 'imani', 'Then better odometry math only gets us so far here. If an old map cannot be trusted, the fix is not integrating a bad reference more carefully -- it is teaching a robot to sense the world directly instead of trusting that map blindly. That is what comes next.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-mobile-robots-01-o1', 'mission-vec-mobile-robots-01', 1, 'Explain differential steering', 'State how a differential-drive robot changes direction using only its two wheel speeds.'),
  ('mission-vec-mobile-robots-01-o2', 'mission-vec-mobile-robots-01', 2, 'Predict the motion', 'Judge which direction, if any, the robot moves for a given pair of wheel speeds.'),

  ('mission-vec-mobile-robots-02-o1', 'mission-vec-mobile-robots-02', 1, 'Define what an encoder reports', 'Choose the accurate description of what a wheel encoder actually measures.'),
  ('mission-vec-mobile-robots-02-o2', 'mission-vec-mobile-robots-02', 2, 'Convert ticks to distance', 'Find the evidence needed to compute how far a wheel actually rotated in a given interval.'),

  ('mission-vec-mobile-robots-03-o1', 'mission-vec-mobile-robots-03', 1, 'Define odometry', 'Choose the accurate description of what odometry actually computes.'),
  ('mission-vec-mobile-robots-03-o2', 'mission-vec-mobile-robots-03', 2, 'Order the odometry loop', 'Put the stages of one odometry update cycle in the order they actually run.'),

  ('mission-vec-mobile-robots-04-o1', 'mission-vec-mobile-robots-04', 1, 'State the kinematic model', 'Choose the accurate description of how a differential-drive robot''s forward speed and turning rate relate to its two wheel speeds.'),
  ('mission-vec-mobile-robots-04-o2', 'mission-vec-mobile-robots-04', 2, 'Judge the effect of track width', 'State how track width changes the turning rate produced by a given wheel-speed difference.'),

  ('mission-vec-mobile-robots-05-o1', 'mission-vec-mobile-robots-05', 1, 'Define a velocity command', 'Choose the accurate description of what a velocity command actually specifies.'),
  ('mission-vec-mobile-robots-05-o2', 'mission-vec-mobile-robots-05', 2, 'Invert the kinematic model', 'Judge the correct wheel speeds for a given velocity command.'),

  ('mission-vec-mobile-robots-06-o1', 'mission-vec-mobile-robots-06', 1, 'Define skid and slip', 'Choose the accurate description of how skid and slip break odometry''s core assumption.'),
  ('mission-vec-mobile-robots-06-o2', 'mission-vec-mobile-robots-06', 2, 'Rule out slip as the full explanation', 'Find the evidence showing slip alone cannot account for this robot''s drift.'),

  ('mission-vec-mobile-robots-07-o1', 'mission-vec-mobile-robots-07', 1, 'Contrast Ackermann steering with differential drive', 'Choose the accurate description of how Ackermann steering achieves turning, and how that differs from this robot''s drivetrain.'),

  ('mission-vec-mobile-robots-08-o1', 'mission-vec-mobile-robots-08', 1, 'Define holonomic drive', 'Choose the accurate description of what makes a drive holonomic, and why this robot is not one.'),

  ('mission-vec-mobile-robots-09-o1', 'mission-vec-mobile-robots-09', 1, 'Define a coordinate transform', 'Choose the accurate description of what a coordinate transform actually does.'),
  ('mission-vec-mobile-robots-09-o2', 'mission-vec-mobile-robots-09', 2, 'Find the missing transform', 'Find the evidence showing this robot''s odometry frame and the facility map''s frame were never reconciled.'),

  ('mission-vec-mobile-robots-10-o1', 'mission-vec-mobile-robots-10', 1, 'Define dead reckoning', 'Choose the accurate description of what dead reckoning actually is and why its error grows over time.'),
  ('mission-vec-mobile-robots-10-o2', 'mission-vec-mobile-robots-10', 2, 'Judge the timeline', 'State what a robot going weeks without external correction implies about when its drift actually began.'),

  ('mission-vec-mobile-robots-11-o1', 'mission-vec-mobile-robots-11', 1, 'Define motion calibration', 'Choose the accurate description of what calibration actually corrects.'),
  ('mission-vec-mobile-robots-11-o2', 'mission-vec-mobile-robots-11', 2, 'Judge calibration''s limits', 'Find the evidence showing recalibration alone does not fully explain this robot''s drift.'),

  ('mission-vec-mobile-robots-12-o1', 'mission-vec-mobile-robots-12', 1, 'Diagnose the drift mechanism', 'Judge what this robot''s own wheel encoders and kinematic model say caused its logged position to diverge.'),
  ('mission-vec-mobile-robots-12-o2', 'mission-vec-mobile-robots-12', 2, 'Confirm against the map', 'Find the evidence confirming the drift as a coordinate-transform mismatch against an outdated facility map, not a hardware problem.'),
  ('mission-vec-mobile-robots-12-o3', 'mission-vec-mobile-robots-12', 3, 'Recognize the pattern', 'Find the evidence showing this is not one robot''s problem but a pattern across the fleet.'),
  ('mission-vec-mobile-robots-12-o4', 'mission-vec-mobile-robots-12', 4, 'State the diagnosis', 'Having judged all three, state what several of the fleet''s reported malfunctions actually are.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-mobile-robots-01-o1-c1', 'mission-vec-mobile-robots-01-o1', 1, 'multiple_choice', 'A differential-drive robot has exactly two powered wheels and no separate steering mechanism. How does it change direction?', '{"question":"A differential-drive robot has exactly two powered wheels and no separate steering mechanism. How does it change direction?","options":[{"id":"a","text":"It cannot change direction without an additional steering wheel"},{"id":"b","text":"By driving its two wheels at different speeds -- the robot curves toward whichever side is moving slower"},{"id":"c","text":"By briefly reversing both wheels at once"},{"id":"d","text":"By tilting its chassis toward the desired direction"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mobile-robots-01-o2-c1', 'mission-vec-mobile-robots-01-o2', 1, 'drag_and_drop', 'Sort each pair of wheel speeds into the motion it actually produces.', '{"items":[{"id":"i1","text":"Left wheel 0.5 m/s, right wheel 0.5 m/s"},{"id":"i2","text":"Left wheel 0.3 m/s, right wheel 0.6 m/s"},{"id":"i3","text":"Left wheel 0.6 m/s, right wheel 0.3 m/s"},{"id":"i4","text":"Left wheel 0.4 m/s, right wheel -0.4 m/s"}],"targets":[{"id":"straight","label":"Drives straight"},{"id":"left","label":"Turns left"},{"id":"right","label":"Turns right"},{"id":"spin","label":"Spins in place"}]}'::jsonb, '{"correctMapping":{"i1":"straight","i2":"left","i3":"right","i4":"spin"}}'::jsonb),

  ('mission-vec-mobile-robots-02-o1-c1', 'mission-vec-mobile-robots-02-o1', 1, 'multiple_choice', 'A wheel encoder''s raw output is best described as...', '{"question":"A wheel encoder''s raw output is best described as...","options":[{"id":"a","text":"The robot''s exact position in the facility"},{"id":"b","text":"A count of discrete ticks marking wheel rotation, which only becomes a distance once combined with the wheel''s known geometry"},{"id":"c","text":"A continuous voltage proportional to the robot''s speed"},{"id":"d","text":"The robot''s heading relative to true north"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mobile-robots-02-o2-c1', 'mission-vec-mobile-robots-02-o2', 1, 'investigation', 'Which two pieces of evidence, together, let Lin compute exactly how far this wheel rotated in the last second?', '{"evidence":[{"id":"e1","label":"Encoder spec sheet","detail":"This wheel''s encoder produces exactly 512 ticks per full revolution"},{"id":"e2","label":"Raw tick log","detail":"1024 ticks counted on the left wheel over the last one-second interval"},{"id":"e3","label":"Facility note","detail":"The charging dock''s guide light was replaced last month"}],"question":"Which two pieces of evidence, together, let Lin compute exactly how far this wheel rotated in the last second?"}'::jsonb, '{"requiredEvidenceIds":["e1","e2"]}'::jsonb),

  ('mission-vec-mobile-robots-03-o1-c1', 'mission-vec-mobile-robots-03-o1', 1, 'multiple_choice', 'Odometry is best described as...', '{"question":"Odometry is best described as...","options":[{"id":"a","text":"A sensor that directly measures the robot''s true position"},{"id":"b","text":"The process of estimating position by repeatedly integrating small motion steps computed from wheel encoder data, with nothing external to correct it"},{"id":"c","text":"A camera-based positioning system"},{"id":"d","text":"A fixed lookup table of known robot locations"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mobile-robots-03-o2-c1', 'mission-vec-mobile-robots-03-o2', 1, 'interactive_diagram', 'Order one odometry update cycle from first to last.', '{"diagramId":"odometry-loop","hotspots":[{"id":"read_ticks","label":"Read encoder ticks","explanation":"Each wheel''s new tick count since the last cycle is read."},{"id":"ticks_to_distance","label":"Convert ticks to distance","explanation":"Tick counts become wheel distances using known wheel geometry."},{"id":"apply_model","label":"Apply the kinematic model","explanation":"Wheel distances become one small step of robot translation and rotation."},{"id":"update_position","label":"Update the position estimate","explanation":"The small step is added onto the last known position estimate."}],"task":"Order one odometry update cycle from first to last."}'::jsonb, '{"correctOrderIds":["read_ticks","ticks_to_distance","apply_model","update_position"]}'::jsonb),

  ('mission-vec-mobile-robots-04-o1-c1', 'mission-vec-mobile-robots-04-o1', 1, 'multiple_choice', 'In a differential-drive robot''s kinematic model, forward speed and turning rate are computed as...', '{"question":"In a differential-drive robot''s kinematic model, forward speed and turning rate are computed as...","options":[{"id":"a","text":"Forward speed equals either wheel speed alone; turning rate is irrelevant"},{"id":"b","text":"Forward speed is the average of the two wheel speeds; turning rate is proportional to their difference divided by the track width"},{"id":"c","text":"Forward speed and turning rate are both fixed constants set at manufacture"},{"id":"d","text":"Forward speed is the sum of both wheel speeds; turning rate is unrelated to wheel speed at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mobile-robots-04-o2-c1', 'mission-vec-mobile-robots-04-o2', 1, 'multiple_choice', 'Two robots have the same wheel-speed difference between their left and right wheels, but one has a wider track width than the other. What happens to their turning rates?', '{"question":"Two robots have the same wheel-speed difference between their left and right wheels, but one has a wider track width than the other. What happens to their turning rates?","options":[{"id":"a","text":"Both turn at exactly the same rate, track width does not matter"},{"id":"b","text":"The robot with the wider track width turns more gently for that same wheel-speed difference; the narrower one turns faster"},{"id":"c","text":"The wider robot always turns faster"},{"id":"d","text":"Track width only affects forward speed, never turning rate"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-mobile-robots-05-o1-c1', 'mission-vec-mobile-robots-05-o1', 1, 'multiple_choice', 'A velocity command sent to a mobile robot typically specifies...', '{"question":"A velocity command sent to a mobile robot typically specifies...","options":[{"id":"a","text":"The exact ticks each encoder should report"},{"id":"b","text":"A desired forward speed and a desired turning rate, which the robot''s own kinematic model then converts into individual wheel speeds"},{"id":"c","text":"A destination coordinate and nothing else"},{"id":"d","text":"The exact voltage to apply to each motor"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mobile-robots-05-o2-c1', 'mission-vec-mobile-robots-05-o2', 1, 'multiple_choice', 'A robot receives the velocity command: forward speed 0.5 m/s, turning rate 0 rad/s. What should its two wheel speeds be?', '{"question":"A robot receives the velocity command: forward speed 0.5 m/s, turning rate 0 rad/s. What should its two wheel speeds be?","options":[{"id":"a","text":"Left wheel 0.5 m/s, right wheel 0 m/s"},{"id":"b","text":"Both wheels at exactly 0.5 m/s -- zero turning rate means zero difference between them"},{"id":"c","text":"Both wheels at 0 m/s"},{"id":"d","text":"Left and right wheels spinning in opposite directions"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-mobile-robots-06-o1-c1', 'mission-vec-mobile-robots-06-o1', 1, 'multiple_choice', 'Skid and slip are best described as...', '{"question":"Skid and slip are best described as...","options":[{"id":"a","text":"A wheel encoder hardware failure"},{"id":"b","text":"Conditions where a wheel''s rotation no longer matches the distance actually traveled -- spinning without full traction, or being dragged without turning enough -- breaking the assumption odometry depends on"},{"id":"c","text":"A software bug in the kinematic model"},{"id":"d","text":"A deliberate braking maneuver"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mobile-robots-06-o2-c1', 'mission-vec-mobile-robots-06-o2', 1, 'investigation', 'Which evidence shows that skid and slip alone cannot explain this robot''s drift?', '{"evidence":[{"id":"e1","label":"Byte''s fleet analysis","detail":"Slip events across the fleet are short, localized to specific floor patches, and self-correct within seconds -- they do not accumulate into a slow, months-long drift"},{"id":"e2","label":"Drift log","detail":"This robot''s position error grew steadily larger every week for months, in a facility zone with no reported spills or floor damage"},{"id":"e3","label":"Maintenance note","detail":"Tires were inspected and found to be in acceptable condition"}],"question":"Which evidence shows that skid and slip alone cannot explain this robot''s drift?"}'::jsonb, '{"requiredEvidenceIds":["e1","e2"]}'::jsonb),

  ('mission-vec-mobile-robots-07-o1-c1', 'mission-vec-mobile-robots-07-o1', 1, 'multiple_choice', 'Ackermann steering achieves turning by...', '{"question":"Ackermann steering achieves turning by...","options":[{"id":"a","text":"Driving two wheels at different speeds, exactly like differential drive"},{"id":"b","text":"Turning the front wheels to slightly different angles from each other, so every wheel can roll along a circle around one shared turn center without slipping sideways"},{"id":"c","text":"Spinning all four wheels in opposite directions"},{"id":"d","text":"Tilting the whole vehicle body toward the turn"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-mobile-robots-08-o1-c1', 'mission-vec-mobile-robots-08-o1', 1, 'multiple_choice', 'A holonomic drive is best described as...', '{"question":"A holonomic drive is best described as...","options":[{"id":"a","text":"Any drivetrain with more than two wheels"},{"id":"b","text":"A drivetrain that can move in any direction, including sideways, independent of its current orientation -- unlike differential drive or Ackermann steering, which can only roll forward, backward and turn"},{"id":"c","text":"A drivetrain that never needs wheel encoders"},{"id":"d","text":"A drivetrain exclusive to aerial robots"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-mobile-robots-09-o1-c1', 'mission-vec-mobile-robots-09-o1', 1, 'multiple_choice', 'A coordinate transform between two reference frames is best described as...', '{"question":"A coordinate transform between two reference frames is best described as...","options":[{"id":"a","text":"A conversion between different units of measurement, like meters and feet"},{"id":"b","text":"A rotation and translation that maps a position expressed in one frame into the equivalent position expressed in another frame"},{"id":"c","text":"A backup copy of a robot''s position log"},{"id":"d","text":"A calibration of a wheel encoder''s tick count"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mobile-robots-09-o2-c1', 'mission-vec-mobile-robots-09-o2', 1, 'investigation', 'Which evidence shows the robot''s odometry frame and the facility map''s frame were never actually reconciled?', '{"evidence":[{"id":"e1","label":"Robot configuration","detail":"Odometry frame origin: the robot''s charging dock, set automatically the first time it powered on"},{"id":"e2","label":"Facility blueprint metadata","detail":"Map frame origin: a survey marker placed during a renovation eleven years ago; no coordinate transform to any robot''s odometry frame is recorded anywhere in the facility database"},{"id":"e3","label":"Maintenance note","detail":"The robot''s charging dock was repainted last quarter"}],"question":"Which evidence shows the robot''s odometry frame and the facility map''s frame were never actually reconciled?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-mobile-robots-10-o1-c1', 'mission-vec-mobile-robots-10-o1', 1, 'multiple_choice', 'Dead reckoning is best described as...', '{"question":"Dead reckoning is best described as...","options":[{"id":"a","text":"A position estimate confirmed by an external reference every cycle"},{"id":"b","text":"A position estimate built purely from integrating a robot''s own motion, with no external correction, whose error compounds the longer it runs uncorrected"},{"id":"c","text":"A GPS-based positioning method"},{"id":"d","text":"A one-time position measurement taken at startup only"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mobile-robots-10-o2-c1', 'mission-vec-mobile-robots-10-o2', 1, 'multiple_choice', 'A robot has gone several weeks without any external correction to its position estimate. What does that imply about when its current drift actually began accumulating?', '{"question":"A robot has gone several weeks without any external correction to its position estimate. What does that imply about when its current drift actually began accumulating?","options":[{"id":"a","text":"The drift only began today, whenever it was first noticed"},{"id":"b","text":"The drift has been accumulating continuously since the last external correction, growing larger every uncorrected cycle in between"},{"id":"c","text":"Dead reckoning error resets automatically every 24 hours"},{"id":"d","text":"Without a correction, the error stays exactly constant over time"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-mobile-robots-11-o1-c1', 'mission-vec-mobile-robots-11-o1', 1, 'multiple_choice', 'Motion calibration for a mobile robot is best described as...', '{"question":"Motion calibration for a mobile robot is best described as...","options":[{"id":"a","text":"Replacing worn hardware with new parts"},{"id":"b","text":"Measuring and correcting the physical constants -- wheel diameter, track width, encoder scale -- that the kinematic model assumes are known, so its distance and turning computations match the real machine"},{"id":"c","text":"Resetting the robot''s odometry estimate to zero"},{"id":"d","text":"A one-time factory step that never needs to be repeated"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mobile-robots-11-o2-c1', 'mission-vec-mobile-robots-11-o2', 1, 'investigation', 'Which evidence shows that recalibrating the wheel diameter does not fully explain this robot''s drift?', '{"evidence":[{"id":"e1","label":"Firmware audit","detail":"This robot''s firmware still uses the factory-spec wheel diameter; direct measurement shows the actual, worn wheels are roughly two percent smaller"},{"id":"e2","label":"Byte''s recalculation","detail":"Correcting the wheel diameter value closes only a portion of the total observed position error; a substantial gap remains even after recalibration"},{"id":"e3","label":"Maintenance note","detail":"Battery replaced on schedule three months ago"}],"question":"Which evidence shows that recalibrating the wheel diameter does not fully explain this robot''s drift?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-mobile-robots-12-o1-c1', 'mission-vec-mobile-robots-12-o1', 1, 'multiple_choice', 'Given nominal wheel encoders, nominal motors, and a kinematic model that correctly converts wheel speeds into estimated motion, what does the robot''s own math say caused its logged position to diverge from where it actually stood?', '{"question":"Given nominal wheel encoders, nominal motors, and a kinematic model that correctly converts wheel speeds into estimated motion, what does the robot''s own math say caused its logged position to diverge from where it actually stood?","options":[{"id":"a","text":"A hardware fault somewhere in the drivetrain"},{"id":"b","text":"Dead reckoning integrating small, ordinary errors over time with no external correction -- drifting further every week even though every individual reading was technically consistent"},{"id":"c","text":"Deliberate tampering with the robot''s firmware"},{"id":"d","text":"Network delay between the robot and the fleet server"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-mobile-robots-12-o2-c1', 'mission-vec-mobile-robots-12-o2', 1, 'investigation', 'Which evidence confirms the drift is a coordinate-frame mismatch against an outdated section of the facility map, not a hardware problem?', '{"evidence":[{"id":"e1","label":"Robot odometry log","detail":"Internally consistent position estimates, a smooth continuous path with no discontinuities anywhere in it"},{"id":"e2","label":"Facility comparison","detail":"The robot''s logged path, rotated and translated by a fixed offset, lines up exactly with its true patrol route -- the offset matches the boundary of a warehouse zone renovated eleven years ago whose blueprint origin was never re-surveyed"},{"id":"e3","label":"Maintenance note","detail":"Tires were replaced eight months ago as a routine wear item"}],"question":"Which evidence confirms the drift is a coordinate-frame mismatch against an outdated section of the facility map, not a hardware problem?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-vec-mobile-robots-12-o3-c1', 'mission-vec-mobile-robots-12-o3', 1, 'investigation', 'Which evidence shows this is not one robot''s problem but a pattern across the fleet?', '{"evidence":[{"id":"e1","label":"Byte''s fleet query","detail":"Six additional robots flagged as malfunctioning this year, each operating in a zone renovated at a different time, every one showing the identical rotated-and-offset path signature once compared against as-built survey data"},{"id":"e2","label":"Maintenance tickets","detail":"Each flagged robot received a new battery, new wheels, or a firmware reflash at some point, none of which changed the drift"},{"id":"e3","label":"Facilities note","detail":"A guest wifi outage occurred the same week as one of the reports"}],"question":"Which evidence shows this is not one robot''s problem but a pattern across the fleet?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-mobile-robots-12-o4-c1', 'mission-vec-mobile-robots-12-o4', 1, 'boss_encounter', 'Having diagnosed the drift, confirmed it against the map, and recognized the pattern across the fleet, state what several of the fleet''s reported malfunctions actually are.', '{"stages":[{"objectiveRef":"mission-vec-mobile-robots-12-o1","label":"Diagnose the drift mechanism"},{"objectiveRef":"mission-vec-mobile-robots-12-o2","label":"Confirm against the map"},{"objectiveRef":"mission-vec-mobile-robots-12-o3","label":"Recognize the pattern"}],"task":"State the diagnosis in one sentence: several of the fleet''s reported malfunctions are not malfunctions at all, but ordinary dead-reckoning drift accumulating against maps and coordinate frames that were never updated as facilities were renovated over the decades -- the same undocumented-frame problem from the arm, now recognized as a pattern across the entire fleet."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-mobile-robots-12-o1","mission-vec-mobile-robots-12-o2","mission-vec-mobile-robots-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-mobile-robots-01-o1-c1', 'orientation', 'Ask what physically changes on the robot when it stops going straight and starts curving.', 10, 1),
  ('mission-vec-mobile-robots-01-o1-c1', 'solution', 'It steers only by driving the two wheels at different speeds -- there is no separate steering mechanism at all.', 20, 2),
  ('mission-vec-mobile-robots-01-o2-c1', 'orientation', 'Compare each pair of speeds: are they equal, is one faster, or are they opposite?', 10, 1),
  ('mission-vec-mobile-robots-01-o2-c1', 'solution', 'Equal speeds drive straight, a slower-left pair turns left, a slower-right pair turns right, and equal-but-opposite speeds spin the robot in place.', 20, 2),

  ('mission-vec-mobile-robots-02-o1-c1', 'orientation', 'An encoder sits on the wheel axle itself, not anywhere in the navigation software.', 10, 1),
  ('mission-vec-mobile-robots-02-o1-c1', 'solution', 'It only counts discrete ticks of rotation -- distance and position both require converting those ticks using the wheel''s known geometry.', 20, 2),
  ('mission-vec-mobile-robots-02-o2-c1', 'orientation', 'You need both the conversion factor and the raw count to get a real number out.', 10, 1),
  ('mission-vec-mobile-robots-02-o2-c1', 'solution', 'e1 gives ticks-per-revolution and e2 gives the raw tick count -- together they convert directly into a distance for that interval.', 20, 2),

  ('mission-vec-mobile-robots-03-o1-c1', 'orientation', 'Odometry never measures position directly -- ask what it builds that estimate out of instead.', 10, 1),
  ('mission-vec-mobile-robots-03-o1-c1', 'concept', 'It repeatedly adds small motion steps, computed from wheel encoder data, onto its last known estimate.', 20, 2),
  ('mission-vec-mobile-robots-03-o1-c1', 'solution', 'Odometry estimates position by integrating small motion steps with nothing external ever correcting it along the way.', 30, 3),
  ('mission-vec-mobile-robots-03-o2-c1', 'orientation', 'Ticks have to be read before they can be converted, and a step of motion has to be computed before it can be added anywhere.', 10, 1),
  ('mission-vec-mobile-robots-03-o2-c1', 'solution', 'Read ticks, convert to distance, apply the kinematic model, then update the position estimate -- and repeat.', 20, 2),

  ('mission-vec-mobile-robots-04-o1-c1', 'orientation', 'Think about what averaging two wheel speeds gives you, versus what their difference gives you.', 10, 1),
  ('mission-vec-mobile-robots-04-o1-c1', 'concept', 'Forward speed comes from combining both wheels equally; turning rate comes from how much they disagree.', 20, 2),
  ('mission-vec-mobile-robots-04-o1-c1', 'solution', 'Forward speed is the average of the two wheel speeds; turning rate is their difference divided by the track width.', 30, 3),
  ('mission-vec-mobile-robots-04-o2-c1', 'orientation', 'Picture the same wheel-speed difference spread across a wider axle versus a narrower one.', 10, 1),
  ('mission-vec-mobile-robots-04-o2-c1', 'solution', 'A wider track width divides that same difference over a larger distance, producing a gentler turn; a narrower one turns faster.', 20, 2),

  ('mission-vec-mobile-robots-05-o1-c1', 'orientation', 'A velocity command describes the whole robot''s motion, not either wheel individually.', 10, 1),
  ('mission-vec-mobile-robots-05-o1-c1', 'solution', 'It specifies a forward speed and a turning rate, which the kinematic model then converts into individual wheel speeds.', 20, 2),
  ('mission-vec-mobile-robots-05-o2-c1', 'orientation', 'Zero turning rate means the two wheel speeds cannot differ at all.', 10, 1),
  ('mission-vec-mobile-robots-05-o2-c1', 'solution', 'With zero turning rate, both wheels must run at exactly the commanded forward speed -- 0.5 m/s each.', 20, 2),

  ('mission-vec-mobile-robots-06-o1-c1', 'orientation', 'Ask what odometry silently assumes is always true about a spinning wheel.', 10, 1),
  ('mission-vec-mobile-robots-06-o1-c1', 'solution', 'Skid and slip are exactly the conditions where wheel rotation no longer matches actual ground travel, breaking odometry''s core assumption.', 20, 2),
  ('mission-vec-mobile-robots-06-o2-c1', 'orientation', 'Compare how long a slip event lasts against how long this robot''s drift has been building.', 10, 1),
  ('mission-vec-mobile-robots-06-o2-c1', 'solution', 'Slip is short and self-correcting, while this robot''s drift grew steadily for months in a zone with no slip conditions reported at all.', 20, 2),

  ('mission-vec-mobile-robots-07-o1-c1', 'orientation', 'Ackermann steering has no independently driven wheels to speed up or slow down -- it has wheels that physically turn.', 10, 1),
  ('mission-vec-mobile-robots-07-o1-c1', 'solution', 'It turns the front wheels to different angles so every wheel can roll, without slipping, around one shared turn center.', 20, 2),

  ('mission-vec-mobile-robots-08-o1-c1', 'orientation', 'Ask whether the robot has to turn its whole body before it can move sideways.', 10, 1),
  ('mission-vec-mobile-robots-08-o1-c1', 'solution', 'A holonomic drive can move in any direction independent of its orientation; differential drive and Ackermann steering both cannot.', 20, 2),

  ('mission-vec-mobile-robots-09-o1-c1', 'orientation', 'A transform relates two different origins and orientations, not two different units.', 10, 1),
  ('mission-vec-mobile-robots-09-o1-c1', 'solution', 'It is a rotation and translation mapping a position in one frame into the equivalent position in another frame.', 20, 2),
  ('mission-vec-mobile-robots-09-o2-c1', 'orientation', 'Look for evidence that names both origins and says whether a transform between them was ever recorded.', 10, 1),
  ('mission-vec-mobile-robots-09-o2-c1', 'concept', 'The robot''s frame and the map''s frame each have their own separate origin, set independently of each other.', 20, 2),
  ('mission-vec-mobile-robots-09-o2-c1', 'solution', 'e2: the map''s frame traces to a decades-old survey marker, and no transform to the robot''s odometry frame exists anywhere in the facility database.', 30, 3),

  ('mission-vec-mobile-robots-10-o1-c1', 'orientation', 'Dead reckoning has no outside reference checking its work at any point.', 10, 1),
  ('mission-vec-mobile-robots-10-o1-c1', 'solution', 'It is a purely integrated estimate whose error compounds the longer it runs without an external correction.', 20, 2),
  ('mission-vec-mobile-robots-10-o2-c1', 'orientation', 'If nothing corrected the estimate this week, when was the last time anything did?', 10, 1),
  ('mission-vec-mobile-robots-10-o2-c1', 'solution', 'The drift has been building continuously since the last correction, not starting the moment it was finally noticed.', 20, 2),

  ('mission-vec-mobile-robots-11-o1-c1', 'orientation', 'Calibration fixes numbers in the firmware, not the physical robot itself.', 10, 1),
  ('mission-vec-mobile-robots-11-o1-c1', 'solution', 'It measures and corrects the physical constants the kinematic model assumes, like wheel diameter and track width, so computations match the real machine.', 20, 2),
  ('mission-vec-mobile-robots-11-o2-c1', 'orientation', 'Look for evidence that says how much of the total error the fix actually closed.', 10, 1),
  ('mission-vec-mobile-robots-11-o2-c1', 'solution', 'e2: Byte''s recalculation shows correcting the wheel diameter closes only part of the total observed error, leaving a substantial gap unexplained.', 20, 2),

  ('mission-vec-mobile-robots-12-o1-c1', 'orientation', 'Nothing hardware-related reported a fault -- ask what kind of error can build up even when every reading is individually correct.', 10, 1),
  ('mission-vec-mobile-robots-12-o1-c1', 'solution', 'Dead reckoning integrating small errors over time, uncorrected, is exactly the mechanism that produces a slow drift with no faulty part anywhere.', 20, 2),
  ('mission-vec-mobile-robots-12-o2-c1', 'orientation', 'Look for evidence comparing the robot''s logged path against its true path once a fixed offset is applied.', 10, 1),
  ('mission-vec-mobile-robots-12-o2-c1', 'solution', 'e2: the logged path matches the true path exactly once rotated and translated by an offset tied to an unresurveyed renovation zone -- a frame mismatch, not a hardware fault.', 20, 2),
  ('mission-vec-mobile-robots-12-o3-c1', 'orientation', 'One robot is a coincidence. Ask what Byte found when the same check ran across the rest of the fleet.', 10, 1),
  ('mission-vec-mobile-robots-12-o3-c1', 'solution', 'e1: six more robots show the identical rotated-and-offset signature, each tied to its own unresurveyed renovation zone -- a pattern, not an isolated case.', 20, 2),
  ('mission-vec-mobile-robots-12-o4-c1', 'orientation', 'Combine what caused the drift, what confirmed it against the map, and how many robots share it into one diagnosis.', 15, 1),
  ('mission-vec-mobile-robots-12-o4-c1', 'solution', 'Several of the fleet''s reported malfunctions are not malfunctions at all -- they are ordinary dead-reckoning drift accumulating against maps and coordinate frames that were never updated as facilities were renovated over the decades, the same undocumented-frame problem from the arm, now recognized as a pattern across the entire fleet.', 25, 2);
